import time

from ute_ue.exceptions import DataTransferIllegalArguments

from taf.ue.android.data_transfer.iperf.direction_specific.abstract_iperf_endpoint import AbstractIperfEndpoint
from taf.ue.android.data_transfer.utils.ip_addr_selector import IpAddressSelector
from taf.ue.android.data_transfer.utils.tcp_port_finder import DEFAULT_PORT_MAX, DEFAULT_PORT_MIN, DEFAULT_PORT_SEARCH_ATTEMPTS, FreeTcpPortFinder
from taf.ue.android.exceptions import NoIpError

NAA_1_4_0_VERSION_CODE = 10
MOBILE_APP_PACKAGE_NAME = 'com.nokia.android.application'


class UeIperfEndpoint(AbstractIperfEndpoint):

    def __init__(self, endpoint_access, dt_name, dt_config, ue_id):
        super().__init__(endpoint_access, dt_name, dt_config)
        self.ue_id = ue_id
        self.__mobile_app_vc = None
        self.__ue_ip = None
        self.iperf_binary = 'iperf' if str(self.dt_config['version']) == "2" else 'iperf3'
        self.last_output_length = 0

    def get_ip(self, retries=8):  # noqa: C901
        """
        Returns ue ip depending on ip version and preferred interface name.
        :param retries: maximal attempt quantity to get any IP address from the device
        :return: IP address or nothing
        """
        ue_interfaces = {}
        if not self.__ue_ip:
            self.logger.debug(f'Getting ip address from UE {self.ue_id}')
            interface_name = self.dt_config['interface_name']
            apn = self.dt_config['robot_kwargs']['apn'] if 'apn' in self.dt_config['robot_kwargs'] else None
            if interface_name and apn:
                raise DataTransferIllegalArguments(f"Cannot choose interface for interface_name={interface_name} "
                                                   f"and apn={apn}. Please provide one parameter")
            ip_version = self.dt_config['app_server']['ip_version']
            for _ in range(retries):
                ue_interfaces = self.endpoint_access.get_ue_info(ue_id=self.ue_id, ue_attributes=['ips'])['ips']
                if ue_interfaces:
                    break
                time.sleep(1.0)
            if ue_interfaces:
                self.logger.debug(f'Network interfaces found on UE {self.ue_id}: {ue_interfaces}')
                # try to get UE ip address via adb cmd
                self.__ue_ip = IpAddressSelector.select_net_interface_ip(network_interfaces_info=ue_interfaces,
                                                                         network_setting=interface_name or apn,
                                                                         ip_version=ip_version, logger=self.logger)
            else:
                self.logger.debug(f'No network interface found via adb on UE {self.ue_id} to bind in iperf')
                # try to get UE ip address via NAA if adb doesn't work
                self.__ue_ip = self.endpoint_access.get_ue_info(ue_id=self.ue_id, ue_attributes=['ip'])['ip']
            self.logger.debug(f"Setting IPv{ip_version} address on UE {self.ue_id} for iperf data transfer: "
                              f"{self.__ue_ip}")
            if not self.__ue_ip:
                raise NoIpError(f"On UE={self.ue_id} cannot get any IP address to perform 'Start Data Transfer'")
        return self.__ue_ip

    def get_bind_ip(self):
        """Return Ip for iperf -B option"""
        if 'apn' in self.dt_config['robot_kwargs'] or self.dt_config['interface_name'] or self.dt_config['bind_ue_ip']:
            return self.get_ip()
        return None

    def start_iperf(self, cmd):
        """
        Runs iperf command on UE
        See implementation of IperfDataTransfer.start() in taf.ue.proxy.access.android
        """
        self.logger.debug(f'Starting iperf on UE: ue_id={self.ue_id}, cmd={cmd}')
        self.endpoint_access.start_data_transfer(ue_id=self.ue_id,
                                                 data_transfer_id=self.dt_name,
                                                 data_transfer_class='AndroidIperf',
                                                 data_transfer_cmd=cmd)

    def kill_iperf(self):
        """
        Stops data transfer on UE
        See implementation of IperfDataTransfer.stop() in taf.ue.proxy.access.android
        """
        self.logger.debug(f'Killing iperf on UE: ue_id={self.ue_id}')
        self.endpoint_access.stop_data_transfer(ue_id=self.ue_id,
                                                data_transfer_id=self.dt_name)

    def kill_iperf_by_port(self, port):
        """
        Stops iperf running on given port on UE.
        """
        self.logger.debug(f'Killing iperf by port on UE: ue_id={self.ue_id}, port={port}')
        self.endpoint_access.kill_process_by_port(ue_id=self.ue_id,
                                                  port=port)

    def is_iperf_running(self):
        """
        Returns true if data transfer on UE is in active state, returns false otherwise
        See implementation of ServiceProxy.get_data_transfer_state() in taf.ue.proxy
        """
        dt_state = self.endpoint_access.get_data_transfer_state(ue_id=self.ue_id,
                                                                data_transfer_id=self.dt_name)
        return dt_state not in ('finished', 'failed', 'stopped')

    def read_iperf_output(self):
        """Return only new iperf lines from UE based on response number of lines"""
        fresh_output = self.endpoint_access.get_data_transfer_output(ue_id=self.ue_id,
                                                                     data_transfer_id=self.dt_name,
                                                                     raw_output=True)['raw_output']
        if len(fresh_output) > self.last_output_length:
            new_lines = fresh_output[self.last_output_length:]
            self.last_output_length = len(fresh_output)
            return new_lines
        return []

    def get_iperf_path(self):
        """Returns path to iperf binary set in config or default path to NAA iperf binary"""
        config_iperf_path = self.dt_config['binary_path']
        if config_iperf_path:
            return self.get_corrected_iperf_path(config_iperf_path, self.iperf_binary)
        return f'/data/data/{MOBILE_APP_PACKAGE_NAME}/{self.iperf_binary}'

    def find_free_port(self, min_port=DEFAULT_PORT_MIN, max_port=DEFAULT_PORT_MAX,
                       attempts=DEFAULT_PORT_SEARCH_ATTEMPTS):
        """
        Finds free port in different way for devices with NAA>=1.4.0
        NAA>=1.4.0 brings a function to check if port is free instead of using netstat output
        """
        # version_code is checked instead of version_name: https://jiradc.ext.net.nokia.com/browse/NAA-326
        # version_code >= 10 == mobile_app_version >= 1.4.0
        if self.mobile_app_version_code >= NAA_1_4_0_VERSION_CODE:
            self.logger.debug(f"{repr(self)}: NAA version >= 1.4.0. Searching random free port without netstat")
            free_port = FreeTcpPortFinder.find_random_free_port(port_validator=self._is_port_free_naa_140_and_higher,
                                                                min_port=min_port,
                                                                max_port=max_port,
                                                                attempts=attempts)
            self.logger.debug(f"{repr(self)}: NAA version >= 1.4.0. Chosen port {free_port}")
            return free_port
        return super().find_free_port(min_port, max_port)

    def is_port_free(self, port):
        # version_code is checked instead of version_name: https://jiradc.ext.net.nokia.com/browse/NAA-326
        # version_code >= 10 == mobile_app_version >= 1.4.0
        if self.mobile_app_version_code >= NAA_1_4_0_VERSION_CODE:
            return self._is_port_free_naa_140_and_higher(port)
        return super().is_port_free(port)

    def list_occupied_ports_on_device(self):
        self.logger.debug(f'{repr(self)}: running netstat command `{self.NETSTAT_OCCUPIED_PORTS_CMD}` on UE.')
        netstat_output = self.endpoint_access.get_occupied_ports(ue_id=self.ue_id)
        self.logger.debug(f'{repr(self)}: netstat output from UE:\n{netstat_output}')
        return netstat_output

    def _is_port_free_naa_140_and_higher(self, port):
        """See https://jiradc.ext.net.nokia.com/browse/UTETAF-4046"""
        self.logger.debug(f"{repr(self)}: NAA version >= 1.4.0. Checking if port {port} is free")
        is_port_free = self.endpoint_access.is_port_free(ue_id=self.ue_id,
                                                         port=port)
        self.logger.debug(f"{repr(self)}: NAA version >= 1.4.0. Port {port} is {self.port_status(is_port_free)}")
        return is_port_free

    @property
    def mobile_app_version_code(self):
        if not self.__mobile_app_vc:
            self.logger.debug(f"{self}: checking mobile app version code.")
            ue_info = 'mobile_app_protocol_version'
            self.__mobile_app_vc = self.endpoint_access.get_ue_info(ue_id=self.ue_id,
                                                                    ue_attributes=[ue_info])[ue_info]
            self.logger.debug(f"{repr(self)}: mobile app version code = {self.__mobile_app_vc}.")
        return self.__mobile_app_vc

